import Avatar from '@mui/material/Avatar';
import Box from '@mui/material/Box';
import { useState } from 'react';

/**
 * Logo images come from logoapi.sh (free, no key; requests go directly from the browser, so the
 * service sees which tickers are displayed). `fallback=404` makes a missing logo an error instead
 * of a generated placeholder, so a neutral monogram can be shown. Some tickers are answered with a
 * name tile generated by the service; the browser cannot tell those apart, so they are shown as
 * returned.
 */
export function logoUrl(ticker: string): string {
  return `https://logoapi.sh/icon/ticker/${encodeURIComponent(ticker)}?fallback=404`;
}

/** Initials for the fallback tile: the ticker's first segment, without an index "^" prefix. */
export function monogram(ticker: string): string {
  return (ticker.replace(/^\^/, '').split(/[.=-]/)[0] ?? ticker).slice(0, 4);
}

/**
 * A stock's logo, or a neutral monogram of its ticker when no logo is available (never another
 * company's logo, never an invented one). Decorative: the name and ticker are always shown next to
 * it. Remount it (key) when the ticker changes.
 */
export function StockLogo({ ticker, size = 44 }: { ticker: string; size?: number }) {
  const [failed, setFailed] = useState(false);
  const initials = monogram(ticker);
  if (failed) {
    return (
      <Avatar
        variant="rounded"
        aria-hidden="true"
        sx={{
          width: size,
          height: size,
          fontSize: size * (initials.length > 3 ? 0.26 : 0.32),
          fontWeight: 700,
          letterSpacing: '0.02em',
          bgcolor: 'action.selected',
          color: 'text.secondary',
        }}
      >
        {initials}
      </Avatar>
    );
  }
  return (
    <Box
      component="img"
      src={logoUrl(ticker)}
      alt=""
      width={size}
      height={size}
      loading="lazy"
      decoding="async"
      onError={() => {
        setFailed(true);
      }}
      // Logos are drawn for light backgrounds: a white tile keeps them legible in dark mode too.
      sx={{
        flexShrink: 0,
        borderRadius: 1.5,
        bgcolor: '#ffffff',
        objectFit: 'contain',
        p: 0.75,
        border: 1,
        borderColor: 'divider',
      }}
    />
  );
}
